import json,hashlib
D={'pages':[],'units':[],'boundary_notes':[],'review_notes':[]}
def p(n,rows):
 pars=[]
 for i,(ar,ru) in enumerate(rows,1):
  id=f'v4-p{n:03}-{i:02}'
  pars.append(dict(id=id,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  D['units'].append(dict(id=id+'-ru',source_ids=[id],printed_pages=[n],ar=ar,ru=ru,draft_status='self_reviewed',print_collation='control_image_read',independent_human_review=False))
 D['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=pars))
def merge(a,b):
 x=next(x for x in D['units'] if a in x['source_ids']); y=next(x for x in D['units'] if b in x['source_ids'])
 x['source_ids']+=y['source_ids']; x['printed_pages']+=y['printed_pages'];x['ar']+=' '+y['ar'];x['ru']+=' '+y['ru'];D['units'].remove(y)
p(329,[('فصل','Раздел'),('قال صاحب «المنازل»: (باب الفناء، قال الله تعالى: {كُلُّ مَنْ عَلَيْهَا فَانٍ وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ} [الرحمن: 26–27]).','Автор «Маназил ас-саирин» сказал: «Глава о фана. Всевышний Аллах сказал: {كُلُّ مَنْ عَلَيْهَا فَانٍ وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ} — “Всякий на ней исчезнет, и останется Лик твоего Господа, Обладателя величия и щедрости” [“Ар-Рахман”, 55:26–27]». '),('الفناء المذكور في الآية ليس هو الفناء الذي تشير إليه الطائفة، فإن الفناء في الآية: الهلاك والعدم، أخبر سبحانه أن كل من على الأرض يعدم ويموت، ويبقى وجهه سبحانه. وهذا مثل قوله: {إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ} [الزمر: 30]، ومثل قوله: {كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ} [آل عمران: 185]، قال الكلبي ومقاتل: لما نزلت هذه الآية قالت الملائكة: هلك أهل الأرض، فلما قال: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88] أيقنت الملائكة بالهلاك.','Фана, упомянутое в аяте, — не то фана, на которое указывают люди этого пути. В аяте оно означает гибель и небытие. Пречистый сообщил, что все находящиеся на земле исчезнут и умрут, а Его Лик останется. Подобны этому слова: {إِنَّكَ مَيِّتٌ وَإِنَّهُمْ مَيِّتُونَ} — «Воистину, ты смертен, и они смертны» [«Аз-Зумар», 39:30], и слова: {كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ} — «Всякая душа вкусит смерть» [«Аль Имран», 3:185]. Аль-Кальби и Мукатиль говорили: «Когда был ниспослан этот аят, ангелы сказали: “Погибли обитатели земли”. Когда же Он сказал: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} — “Всякая вещь погибнет, кроме Его Лика” [“Аль-Касас”, 28:88], ангелы убедились, что погибнут и они». '),('قال الشعبي: إذا قرأت {كُلُّ مَنْ عَلَيْهَا فَانٍ} [الرحمن: 26] فلا تسكت حتى تقرأ {وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ} [الرحمن: 27]. وهذا من فقهه في القرآن وكمال علمه، إذ المقصود الإخبار بفناء من عليها مع بقاء وجهه سبحانه، فإن الآية سيقت لتمدحه بالبقاء وحده، ومجرد فناء الخليقة ليس فيه مدح، إنما المدح في بقائه بعد فناء خلقه، فهي نظير قوله: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} [القصص: 88].','Аш-Шаби говорил: «Когда читаешь {كُلُّ مَنْ عَلَيْهَا فَانٍ} — “Всякий на ней исчезнет” [“Ар-Рахман”, 55:26], не останавливайся, пока не прочтёшь {وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلَالِ وَالْإِكْرَامِ} — “И останется Лик твоего Господа, Обладателя величия и щедрости” [“Ар-Рахман”, 55:27]». Это свидетельствует о его понимании Корана и полноте знания: цель — сообщить об исчезновении всех на земле вместе с пребыванием Его Лика. Аят приведён для восхваления Его одного как Пребывающего. Само исчезновение творений похвалы не содержит; похвала заключена в том, что Он пребывает после исчезновения Своих творений. Этот аят подобен словам: {كُلُّ شَيْءٍ هَالِكٌ إِلَّا وَجْهَهُ} — «Всякая вещь погибнет, кроме Его Лика» [«Аль-Касас», 28:88].')])
p(330,[('وأما الفناء الذي يترجم عليه الطائفة، فأمر غير هذا، ولكن وجه الإشارة بالآية: أن الفناء المشار إليه هو ذهاب القلب وخروجه من هذا العالم، وتعلقه بالعلي الكبير الذي له البقاء فلا يدركه الفناء، ومن فني في محبته وطاعته وإرادة وجهه أوصله هذا الفناء إلى منزل البقاء، فالآية تشير إلى أن العبد حقيق أن لا يتعلق بمن هو فان ويذر من له البقاء، وهو ذو الجلال والإكرام؛ فكأنه يقول: إذا تعلقت بمن هو فان انقطع ذلك التعلق عند فنائه أحوج ما تكون إليه، وإذا تعلقت بمن هو باق لا يفنى لم ينقطع تعلقك ودام بدوامه.','Фана, которому посвящают эту главу люди пути, означает иное. Однако связь с аятом состоит в том, что подразумеваемое фана — уход сердца из этого мира и его привязанность к Возвышенному, Великому, Которому принадлежит пребывание и Которого не достигает исчезновение. Кто поглощён любовью к Нему, покорностью Ему и желанием Его Лика, того такое фана приводит к стоянке пребывания. Аят указывает: рабу подобает не привязываться к исчезающему, оставляя Того, Кому принадлежит пребывание, Обладателя величия и щедрости. Словно говорится: если ты привяжешься к исчезающему, связь прервётся при его исчезновении, когда ты будешь больше всего в ней нуждаться. Если же привяжешься к Пребывающему, Который не исчезнет, твоя связь не прервётся и будет длиться вместе с Его пребыванием.'),('والفناء الذي يترجم عليه هو غاية التعلق ونهايته، فإنه انقطاع عما سوى الرب تعالى من كل وجه، ولذلك قال: (الفناء في هذا الباب: اضمحلال ما دون الحق علما، ثم جحدا، ثم حقا).','Фана, которому посвящена эта глава, есть предельная степень привязанности, её вершина: полное отрешение от всего, кроме Всевышнего Господа. Поэтому он сказал: «Фана в этой главе — исчезновение всего, кроме Истинного: вначале в знании, затем через отрицание, затем в действительности».'),('قلت: الفناء ضد البقاء، والباقي إما باق بنفسه من غير حاجة إلى من يبقيه، بل بقاؤه من لوازم نفسه، وهو الله تعالى وحده، وما سواه فبقاؤه بإبقاء الرب تعالى له، وليس له من نفسه بقاء، كما أنه ليس له من نفسه وجود، فإيجاده وإبقاؤه من ربه وخالقه، وإلا فهو ليس له من نفسه إلا العدم قبل إيجاده، والفناء بعد إيجاده. وليس المعنى: أن نفسه وذاته اقتضت عدمه وفناءه، وإنما المعنى أنك إذا نظرت إلى ذاته بقطع النظر عن إيجاد موجده له كان معدوما، وإذا نظرت إليه بعد وجوده مع قطع النظر عن إبقاء','Я скажу: исчезновение противоположно пребыванию. Пребывающее либо пребывает само по себе, не нуждаясь в том, кто сохранял бы его, причём пребывание неотделимо от его сущности, — таков один лишь Всевышний Аллах; всё остальное пребывает благодаря тому, что Всевышний Господь сохраняет его. Само по себе оно не обладает ни пребыванием, ни существованием: существование и пребывание ему даёт его Господь и Творец. Иначе само по себе оно имеет лишь небытие до своего сотворения и исчезновение после него. Это не означает, что его сущность сама требует его небытия и исчезновения. Смысл в том, что если рассмотреть его сущность без учёта того, что Создатель дал ему существование, оно не существует; а если рассмотреть его после возникновения, отвлекаясь от того, что сохраняет его')])
p(331,[('موجده له استحال بقاؤه، فإنه إنما يبقى بإبقائه، كما أنه إنما يوجد بإيجاده؛ فهذا معنى قولنا: إنه بنفسه معدوم وفان، فافهمه.','его Создатель, его пребывание окажется невозможным. Ведь оно пребывает лишь потому, что Он сохраняет его, как и существует лишь потому, что Он дал ему существование. Вот смысл наших слов, что само по себе оно не существует и исчезает. Пойми это.'),('وقد اختلف الناس: هل إفناء الموجود وإعدامه بخلق عرض فيه يسمى الفناء والإعدام، أم بإمساك خلق البقاء له، إذ هو في كل وقت محتاج إلى أن يخلق له بقاء يبقيه؟ وهي مسألة الإعدام المشهورة.','Люди разошлись во мнениях: происходит ли исчезновение существующего и обращение его в небытие посредством сотворения в нём свойства, именуемого исчезновением и уничтожением, или посредством прекращения творения для него пребывания, поскольку каждое мгновение оно нуждается в сотворении пребывания, которое его сохраняет? Это известный вопрос об уничтожении.'),('والتحقيق فيها: أن ذاته لا تقتضي الوجود، وهو معدوم بنفسه، فإذا قدر الرب تعالى لوجوده أجلا ووقتا انتهى وجوده عند حضور أجله، فرجع إلى أصله وهو العدم.','Верное решение таково: его сущность не требует существования, и само по себе оно не существует. Когда Всевышний Господь устанавливает срок и время его существования, с наступлением срока его существование прекращается и оно возвращается к исходному состоянию — небытию.'),('نعم، قد يقدر له وقتا ثم يمحو ذلك — سبحانه — ويريد إعدامه قبل وقته، كما يمحو ما يشاء، ويريد استمرار وجوده بعد الوقت المقدر إلى أمد آخر، فإنه يمحو ما يشاء ويثبت، فقال تعالى حاكيا عن نبيه نوح: {فَقَالَ يَا قَوْمِ إِنِّي لَكُمْ نَذِيرٌ مُبِينٌ أَنِ اعْبُدُوا اللَّهَ وَاتَّقُوهُ وَأَطِيعُونِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَى أَجَلٍ مُسَمًّى} [نوح: 2–4]، فإذا أراد سبحانه إبقاء الشيء أبقاه إلى حين يشاء، وإذا أراد إفناءه أعدمه بمشيئته، كما يوجده بمشيئته.','Да, Он может назначить ему срок, а затем стереть это — пречист Он — и пожелать уничтожить его раньше срока, как стирает то, что пожелает; либо пожелать продлить его существование после назначенного времени до другого срока. Ведь Он стирает и утверждает то, что пожелает. Всевышний передал слова Своего пророка Нуха: {فَقَالَ يَا قَوْمِ إِنِّي لَكُمْ نَذِيرٌ مُبِينٌ أَنِ اعْبُدُوا اللَّهَ وَاتَّقُوهُ وَأَطِيعُونِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَى أَجَلٍ مُسَمًّى} — «Он сказал: “О мой народ! Я для вас — ясный предостерегающий увещеватель. Поклоняйтесь Аллаху, бойтесь Его и повинуйтесь мне. Он простит вам ваши грехи и даст вам отсрочку до назначенного срока”» [«Нух», 71:2–4]. Если Пречистый желает сохранить вещь, Он сохраняет её до тех пор, пока пожелает; если желает её исчезновения, обращает её в небытие Своей волей, как Своей волей даёт ей существование.'),('فإن قيل: متعلق المشيئة لا بد أن يكون أمرا وجوديا، فكيف يكون العدم متعلق المشيئة؟','Если скажут: «Предметом воли непременно должно быть нечто существующее. Как же небытие может быть предметом воли?»'),('قيل: متعلق المشيئة أمران: إيجاد وإعدام، وكلاهما ممكن، فقول القائل لا بد أن يكون متعلق المشيئة أمرا وجوديا دعوى باطلة. نعم، العدم المحض لا تتعلق به المشيئة، وأما الإعدام فهو أخص من العدم. ولولا أنا في أمر غير هذا','то ответим: воля обращается к двум вещам — дарованию существования и обращению в небытие; и то и другое возможно. Утверждение, будто предмет воли обязательно должен быть существующим, ложно. Да, к чистому небытию воля не относится, однако обращение в небытие — понятие более узкое, чем небытие. Если бы мы не обсуждали сейчас другое,')])
p(332,[('لبسطنا الكلام في هذه المسألة، وذكرنا أوهام الناس وأغلاطهم فيها.','мы подробно изложили бы этот вопрос и упомянули людские заблуждения и ошибки в нём.'),('قوله: (الفناء اسم لاضمحلال ما دون الحق علما)، يعني: يضمحل عن القلب والشهود علما وإن لم يعرض ذاته فانية في الحال مضمحلة، فتغيب صور الموجودات في شهود العبد، بحيث كأنها دخلت في العدم كما كانت قبل أن توجد، ويبقى الحق تعالى ذو الجلال والإكرام وحده في قلب الشاهد كما كان وحده قبل إيجاد العوالم.','Его слова «Фана — название исчезновения всего, кроме Истинного, в знании» означают: это исчезает из сердца и созерцания на уровне знания, хотя человек и не представляет саму его сущность в этот момент исчезающей и угасающей. Образы существующих вещей скрываются в созерцании раба, словно они ушли в небытие, как до своего возникновения. В сердце созерцающего остаётся один лишь Всевышний Истинный, Обладатель величия и щедрости, как Он был один до сотворения миров.'),('وقوله: (علما، ثم جحدا، ثم حقا)، هذه الثلاثة هي مراتب الاضمحلال إذ ورد على العبد على الترتيب، فإذا جاء وهلة واحدة لم يشهد شيئا من ذلك، وإن كان قد يعرف ذلك إذا عاد إلى علمه وشهوده، فإن الرب سبحانه إذا رقى عبده بالتدريج نور باطنه وعقله بالعلم، فرأى أنه لا خالق سواه، ولا رب غيره، ولا يملك الضر والنفع والعطاء والمنع غيره، وأنه لا يستحق أن يعبد بنهاية الخضوع والحب سواه، وكل معبود سوى وجهه الكريم فباطل، فهذا توحيد العلم.','Его слова «вначале в знании, затем через отрицание, затем в действительности» обозначают три ступени исчезновения, когда оно приходит к рабу последовательно. Если же оно наступает сразу, он не созерцает ничего из этого, хотя может распознать это, вернувшись к своему знанию и созерцанию. Когда Пречистый Господь постепенно возвышает Своего раба, Он озаряет его внутренний мир и разум знанием. Тот видит, что нет творца иного, кроме Него, нет иного Господа, что никто иной не владеет причинением вреда и пользы, дарованием и удержанием и что никто, кроме Него, не заслуживает поклонения с предельным смирением и любовью. Всякий объект поклонения, кроме Его благородного Лика, ложен. Это единобожие знания.'),('ثم إذا رقاه الحق سبحانه درجة أخرى فوق هذه أشهده عود المفعولات إلى أفعاله سبحانه، وعود أفعاله إلى أسمائه وصفاته، وقيام صفاته بذاته؛ فيضمحل شهود غيره من قلبه، وجحد أن يكون لسواه من نفسه شيء البتة، ولم يجحد وجود السوى كما يجحده الملاحدة، فإن هذا','Затем, когда Пречистый Истинный поднимает его ещё на ступень выше, Он даёт ему созерцать восхождение результатов действий к Его действиям, восхождение Его действий к Его именам и атрибутам и пребывание Его атрибутов в Его Сущности. Тогда из сердца исчезает созерцание иного, и человек отрицает, что что-либо помимо Него имеет само от себя хоть что-нибудь. Он не отрицает существования иного, как отрицают его безбожники, ибо это')])
merge('v4-p330-03','v4-p331-01');merge('v4-p331-06','v4-p332-01')
p(333,[('الجحود عين الإلحاد.','отрицание и есть безбожие.'),('ثم إذا رقاه درجة أخرى أشهده قيام العوالم كلها — جواهرها وأعراضها، ذواتها وصفاتها — به وحده، أي بإقامته لها وإمساكه لها، فإنه سبحانه يمسك السماوات والأرض أن تزولا، ويمسك البحار أن تغيض أو تفيض على العالم، ويمسك السماء أن تقع على الأرض، ويمسك الطير في الهواء صافات ويقبضن، ويمسك القلوب الموقنة أن تزيغ عن الإيمان، ويمسك حياة الحيوان أن تفارقه إلى الأجل المحدود، ويمسك على الموجودات وجودها، ولولا ذلك لاضمحلت وتلاشت، والكل قائم بأفعاله وصفاته التي هي من لوازم ذاته، فليس الوجود الحقيقي إلا له، أعني الوجود الذي هو مستغن فيه عن سواه، وكل ما سواه فقير إليه بالذات، لا قيام له بنفسه طرفة عين.','Затем, когда Он поднимает его ещё на ступень, Он даёт ему созерцать, что все миры — их субстанции и свойства, сущности и атрибуты — держатся одним лишь Им, то есть тем, что Он поддерживает и удерживает их. Пречистый удерживает небеса и землю, чтобы они не сдвинулись; удерживает моря, чтобы они не иссякли и не затопили мир; удерживает небо, чтобы оно не упало на землю; удерживает птиц в воздухе, когда они расправляют и складывают крылья; удерживает убеждённые сердца от уклонения от веры; удерживает жизнь живого существа, чтобы она не покинула его до назначенного срока; сохраняет существование существующих вещей. Без этого они исчезли бы и рассеялись. Всё держится Его действиями и атрибутами, неотделимыми от Его Сущности. Поэтому подлинное существование принадлежит лишь Ему — я имею в виду существование, не нуждающееся ни в ком ином. Всё остальное по самой своей сущности нуждается в Нём и не может существовать самостоятельно даже мгновение ока.'),('ولما كان للفناء مبدأ وتوسط وغاية، أشار إلى مراتبه الثلاثة؛ فالمرتبة الأولى: فناء أهل العلم المتحققين به، والثاني: فناء أهل السلوك والإرادة، والثالث: فناء أهل المعرفة، المستغرقين في شهود الحق سبحانه.','Поскольку у фана есть начало, середина и предел, он указал на три его ступени. Первая — фана людей знания, осуществивших его; вторая — фана людей духовного пути и стремления; третья — фана людей познания, поглощённых созерцанием Пречистого Истинного.'),('فأول الأمر أن تفنى قوة علمه وشعوره بالمخلوقين في جنب علمه ومعرفته بالله وحقوقه. ثم يقوى ذلك حتى يعدهم كالأموات وكالعدم. ثم يقوى ذلك حتى يغيب عنهم، بحيث يكلم ولا يسمع، ويمر به ولا يرى؛','Вначале сила его знания о творениях и их восприятия меркнет перед его знанием Аллаха, познанием Его и Его прав. Затем это усиливается настолько, что он считает их подобными мёртвым и небытию. Далее это усиливается до такой степени, что он перестаёт замечать их: к нему обращаются, а он не слышит; проходят мимо него, а он не видит;')])
p(334,[('وذلك أبلغ من حال السكر، ولكن لا تدوم له هذه الحال، ولا يمكن أن يعيش عليها.','и это превосходит состояние опьянения. Однако такое состояние не сохраняется постоянно, и жить в нём невозможно.'),('فصل','Раздел'),('قال: (وهو على ثلاث درجات. الدرجة الأولى: فناء المعرفة في المعروف وهو الفناء علما، وفناء العيان في المعاين وهو الفناء جحدا، وفناء الطلب في الوجود وهو الفناء حقا).','Он сказал: «Оно имеет три степени. Первая степень: исчезновение познания в Познаваемом — это фана в знании; исчезновение непосредственного видения в Созерцаемом — это фана через отрицание; исчезновение поиска в обретении — это фана в действительности».'),('هذا تفصيل ما أجمله أولا، وتبيين ما أراد بالعلم والجحد والحق.','Здесь он подробно разъясняет сказанное ранее в общем виде и поясняет, что имел в виду под знанием, отрицанием и действительностью.'),('فـ(فناء المعرفة في المعروف) هو غيبة العارف بمعروفه عن شعوره بمعرفته ومعانيها، فيفنى به سبحانه عن وصفه هو وما قام به، فإن المعرفة فعله ووصفه، فإذا استغرق في شهود المعروف فني عن صفة نفسه وفعلها. ولما كانت المعرفة فوق العلم أخص منه كان فناء المعرفة في المعروف مستلزما لفناء العلم في المعرفة، فيفنى أولا في المعرفة ثم تفنى المعرفة في المعروف.','«Исчезновение познания в Познаваемом» — это поглощённость познающего своим Познаваемым, при которой он перестаёт ощущать своё познание и заключённые в нём смыслы. Пречистый поглощает его внимание, так что он не замечает собственного свойства и того, что ему присуще, ведь познание — его действие и свойство. Когда он погружается в созерцание Познаваемого, он перестаёт замечать свойство и действие собственной души. Поскольку познание выше знания и уже его по смыслу, исчезновение познания в Познаваемом предполагает исчезновение знания в познании. Вначале оно исчезает в познании, затем познание исчезает в Познаваемом.'),('وأما (فناء العيان في المعاين)، فالعيان فوق المعرفة، فإن المعرفة مرتبة فوق العلم ودون العيان، فإذا انتقل من المعرفة إلى العيان فني عيانه في معاينه، كما فنيت معرفته في معروفه.','Что касается «исчезновения непосредственного видения в Созерцаемом», то непосредственное видение выше познания: познание стоит выше знания, но ниже непосредственного видения. Перейдя от познания к непосредственному видению, человек перестаёт замечать своё видение в Созерцаемом, как его познание исчезло в Познаваемом.'),('وأما (فناء الطلب في الوجود)، فهو أن لا يبقى لصاحب هذا الفناء طلب، لأنه ظفر بالمطلوب المشاهد، وصار واجدا بعد أن كان طالبا، فكان إدراكه','Что же касается «исчезновения поиска в обретении», то оно означает, что у находящегося в таком фана не остаётся поиска, поскольку он достиг искомого, которое созерцает, и после поиска стал обретшим. Его постижение')])
p(335,[('أولا علما، ثم قوي فصار معرفة، ثم قوي فصار عيانا، ثم تمكن فصار وجودا.','вначале было знанием, затем усилилось и стало познанием, затем усилилось и стало непосредственным видением, затем утвердилось и стало обретением.'),('ولعلك أن تستنكر أو تستبعد هذه الألفاظ ومعانيها، فاسمع ضرب مثل يسهل عليك ذلك ويقربه منك: مثل ملك عظيم السلطان، شديد السطوة، تام الهيمنة، قوي البأس، استدعى رجلا من رعيته قد اشتد جرمه وعصيانه له، فحضر بين يديه، وغلب على ظنه إتلافه له، فأحواله في حال حضوره مختلفة بالنسبة إلى ما يشاهده، فتارة يتذكر جرمه وسطوة السلطان وقدرته عليه فيفكر فيما يلقاه، وتارة تقهره الحال التي هو فيها فلا يذكر ما كان منه ولا ما أحضر له، لغلبة الخوف على قلبه ويأسه من الخلاص، ولكن عقله وذهنه معه، وتارة يغيب قلبه وذهنه بالكلية فلا يشعر أين هو، ولا من إلى جانبه، ولا بما يراد به، وربما جرى على لسانه في هذه الحال ما لا يريده، فهذا فناء الخوف.','Возможно, эти выражения и их смыслы покажутся тебе неприемлемыми или далёкими от понимания. Тогда выслушай пример, который облегчит их понимание и приблизит их к тебе. Представь царя с огромной властью, грозной силой, полным господством и великой мощью, который вызвал одного из своих подданных, совершившего тяжкое преступление и ослушавшегося его. Тот предстал перед ним и решил, что царь, скорее всего, его погубит. Во время этого предстояния его состояния различаются в зависимости от того, что он видит. То он вспоминает своё преступление, силу царя и его власть над ним и размышляет о том, что ему предстоит. То овладевшее им состояние подавляет его так, что он не помнит ни своих поступков, ни причины, по которой его вызвали: страх переполняет сердце, и он отчаивается спастись, хотя разум и сознание остаются при нём. А иногда его сердце и сознание полностью отключаются: он не чувствует, где находится, кто рядом с ним и что с ним собираются сделать. В таком состоянии его язык может произнести то, чего он не желает. Это фана от страха.'),('ومثال ثان في فناء الحب: محب استغرقت محبته شخصا في غاية الجمال والبهاء، وأكبر أمنيته الوصول إليه ومحادثته ورؤيته، فبينا هو على حاله — وقد ملأ الحب قلبه، وقد استغرق فكره في محبوبه — وإذا به قد','Другой пример — фана от любви. Человека целиком захватила любовь к тому, кто обладает предельной красотой и великолепием; высшая его мечта — добраться до него, беседовать с ним и видеть его. И вот, когда любовь уже наполнила его сердце и мысли целиком погрузились в любимого, тот вдруг')])
p(336,[('دخل عليه بغتة على أحسن هيئة، فقابله قريبا منه، وليس دونه سواه، أفليس هذا حقيقا أن يفنى عن رؤية غيره بمشاهدته، وأن يفنى عن شهوده بمشهوده، بل وعن حبه بمحبوبه؟ فيملك عليه المحبوب سمعه وبصره وإرادته وإحساسه، ويغيب به عن ذاته وصفاته؟','неожиданно входит к нему в прекраснейшем облике и оказывается совсем близко, так что никто иной их не разделяет. Разве не естественно, что созерцание любимого поглотит его настолько, что он перестанет видеть кого-либо ещё, что сам акт созерцания исчезнет для него в созерцаемом и даже любовь — в любимом? Любимый овладевает его слухом, зрением, волей и чувствами, и из-за него он перестаёт замечать собственную сущность и свойства.'),('وانظر إلى النسوة كيف قطعن أيديهن لما طلع عليهن يوسف وشاهدن ذلك الجمال، ولم يتقدم لهن من عشقه ومحبته ما تقدم لامرأة العزيز؛ بل أفناهن شهود جماله عن حالهن حتى قطعن أيديهن. وأما امرأة العزيز؛ فإنها وإن كانت صاحبة المحبة، فإنها كانت قد ألفت رؤيته ومشاهدته، فلما خرج لم يتغير عليها حالها كما تغير على العواذل، فكان مقامها البقاء ومقامهن الفناء، وحصل لهن الفناء من وجهين:','Посмотри на женщин, порезавших себе руки, когда к ним вышел Юсуф и они увидели эту красоту. Прежде они не испытывали такой влюблённости и любви к нему, какую испытывала жена вельможи. Но созерцание его красоты отвлекло их от собственного состояния настолько, что они порезали себе руки. Что же касается жены вельможи, то, хотя именно она любила его, она уже привыкла видеть и созерцать его. Когда он вышел, её состояние не изменилось так, как изменилось состояние порицавших её женщин. Её стоянкой было пребывание, а их — фана. Их фана проявилось в двух отношениях:'),('أحدهما: ذهولهن عن الشعور بقطع ما في أيديهن حتى تخطاه القطع إلى الأيدي.','Первое: они перестали чувствовать, как режут находившееся у них в руках, пока порез не перешёл на сами руки.'),('الثاني: فناؤهن عن الإحساس بألم القطع. وهكذا الفناء بالمخوف والفرح بالمحبوب يفني صاحبه عن شعوره وعن إحساسه بالكيفيات النفسانية.','Второе: они перестали ощущать боль порезов. Подобным образом поглощённость тем, чего страшатся, и радость о любимом отвлекают человека от восприятия себя и от ощущения состояний собственной души.'),('هذا في مشاهدة مخلوق محدث له أشباه وأمثال، وله من يقاربه ويدانيه في الجمال، وإنما فاق بني جنسه في الحسن والجمال بعض الصفات، وامتاز بعض المعاني المخلوقة المصنوعة. فما الظن بمن له الجمال كله، والكمال كله، والإحسان والإجمال، ونسبة كل جمال في الوجود إلى جماله وجلاله','И всё это — при созерцании сотворённого, возникшего существа, у которого есть подобные ему и схожие с ним, а также те, кто близок к нему по красоте. Он превзошёл себе подобных в красоте и привлекательности лишь некоторыми свойствами и выделился некоторыми сотворёнными, созданными качествами. Что же сказать о Том, Кому принадлежат вся красота, всё совершенство, благодеяние и прекрасное обхождение, и по отношению к Чьей красоте и величию всякая красота в бытии')])
merge('v4-p332-04','v4-p333-01');merge('v4-p333-04','v4-p334-01');merge('v4-p334-07','v4-p335-01');merge('v4-p335-03','v4-p336-01')
p(337,[('أقل من نسبة سراج ضعيف إلى عين الشمس؟','значит меньше, чем слабый светильник по отношению к самому солнцу?'),('ولما علم سبحانه أن قوى الأبصار لا تحتمل في هذه الدار رؤيته، احتجب عن عباده إلى يوم لقائه، فينشئهم نشأة يتمكنون بها من مشاهدة جماله ورؤية وجهه؛ وأنت ترى بعض آياته ومخلوقاته ومبدعاته كيف يفنى فيها مشاهدها عن غيرها!','Поскольку Пречистый знает, что сила зрения не выдержит созерцания Его в этой обители, Он скрылся от Своих рабов до дня встречи с Ним. Тогда Он создаст их в таком облике, который позволит им созерцать Его красоту и видеть Его Лик. А ведь ты видишь, как при созерцании лишь некоторых Его знамений, творений и дивных созданий созерцающий перестаёт замечать всё остальное!'),('ولكن هذا كله في المشاهدات العينية، والواردات الوجدانية. وأما المعارف الإلهية، فإن حالة البقاء فيها أكمل من حالة الفناء، وهي حالة نبينا صلوات الله وسلامه عليه، وحال الكمل من أتباعه، ولهذا رأى ما رأى ليلة الإسراء وهو ثابت القلب، رابط الجأش، حاضر الإدراك، تام التمييز، ولو رأى غيره بعض بعض ذلك لما تمالك.','Но всё это относится к непосредственным созерцаниям и наплывам сердечных переживаний. Что же касается познаний об Аллахе, то состояние пребывания в них совершеннее состояния фана. Таково состояние нашего Пророка, да благословит его Аллах и приветствует, и совершенных его последователей. Именно поэтому он увидел то, что увидел в ночь перенесения, сохраняя стойкость сердца, самообладание, ясность восприятия и полноту различения. Если бы другой увидел даже малую долю части этого, он не смог бы владеть собой.'),('فإن قلت: ربما أفهم معنى فناء المعرفة في المعروف وفناء العيان في المعاين، فما معنى (فناء الطلب في الوجود)، حتى يكون (هو الفناء حقا)؟','Если ты скажешь: «Возможно, я понимаю смысл исчезновения познания в Познаваемом и непосредственного видения в Созерцаемом. Но что означает “исчезновение поиска в обретении”, чтобы оно было “фана в действительности”?»'),('قلت: متى فهمت الأمرين اللذين قبله فهمت معناه، فإن الواجد لما ظفر بموجوده فني طلبه له واضمحل. وهذا مشهود في الشاهد، فإنك ترى طالب أمر مهم إذا ظفرت يداه به وبرد له كيف يفنى طلبه في وجوده. لكن هذا','я отвечу: поняв два предыдущих положения, ты поймёшь и его смысл. Когда обретший достиг обретённого, его поиск исчез и рассеялся. Это наблюдается в повседневной жизни: ты видишь, как человек ищет нечто важное, а когда овладевает им и оно прочно ему достаётся, его поиск исчезает в обретении. Однако такое')])
p(338,[('محال في حق العارف، فإن طلبه لا يفارقه، بل إذا وجد اشتد طلبه، فلا يزال طالبا، فكلما كان أوجد كان أطلب.','невозможно в отношении познавшего: поиск его не покидает. Напротив, когда он обретает, его поиск усиливается. Он непрестанно ищет, и чем полнее его обретение, тем сильнее поиск.'),('نعم، الذي يفنى: طلب حظه في طلب محبوبه وطلب مراضيه، وليس بعد هذا غاية، ولكن الذي يشير إليه القوم: أن العبد يصل في منزلة المحبة والمعرفة والاستغراق في المشاهدة إلى حالة يستولي عليه أنوار القرب وآثار الصفات بحيث يذهل لبه عن شعوره وطلبه وإرادته ومحبته.','Да, исчезает стремление к собственной доле, когда человек ищет своего Любимого и того, что Ему угодно. Выше этого нет цели. Но люди пути указывают на то, что на стоянке любви, познания и погружения в созерцание раб достигает состояния, в котором свет близости и проявления атрибутов овладевают им настолько, что его разум перестаёт замечать собственные ощущения, поиск, волю и любовь.'),('وإيضاح ذلك: أن العبد إذا أقبل على ربه، وتفقد أحواله، وتمكن من شهود قيام ربه عليه، فإنه يكون في أول أمره مكابدا مصابرا؛ فإذا صبر وصابر ورابط — صبر في نفسه، وصابر عدوه، ورابط على ثغر قلبه أن يدخل فيه خاطر لا يحبه وليه الحق — ظهر حينئذ في قلبه نور من إقباله على ربه، فإذا قوي ذلك النور غيبه عن وجوده الذهني، وسري به في مطاوي الغيب، وحينئذ يصفو له إقباله على ربه، فإذا صفا له ذلك غاب عن وجوده العيني والذهني، فغاب بنور إقباله على ربه لوصول خالص الذكر وصافيه إلى قلبه، حيث خلا من كل شاغل من الوجود العيني والذهني، وصار واحدا لواحد، فيستولي نور المراقبة على أجزاء باطنه؛ فيمتلئ قلبه من نور التوجه، بحيث يغمر قلبه ويستره عما سواه؛ ثم يسري ذلك النور من باطنه ويعم أجزاء ظاهره، فيتشابه الظاهر والباطن فيه. وحينئذ يفنى العبد عما سواه، ويبقى بالمشهد الروحي الذاتي الموجب للمحبة الخاصة الملهبة للروح.','Разъяснение таково. Когда раб обращается к своему Господу, проверяет собственные состояния и утверждается в созерцании того, что Господь непрестанно печётся о нём, вначале он испытывает тяготы, борется и проявляет стойкость. Но когда он терпит, противостоит и несёт стражу — терпит сам, стойко противостоит врагу и охраняет рубеж своего сердца от проникновения мысли, которую не любит его Истинный Покровитель, — в его сердце появляется свет обращения к Господу. Усилившись, этот свет отвлекает его от существования в мысли и уносит в глубины сокровенного. Тогда его обращённость к Господу становится чистой. Когда она очистится, он перестаёт замечать своё существование и во внешней действительности, и в мысли: свет обращения к Господу поглощает его, ибо в сердце достигает чистое, незамутнённое поминание. Сердце освободилось от всего отвлекающего во внешней действительности и в мысли, и он стал одним, обращённым к Одному. Свет непрестанного наблюдения за собой перед Аллахом овладевает всеми частями его внутреннего мира; сердце наполняется светом устремления, который охватывает его и закрывает от всего остального. Затем этот свет распространяется изнутри на все части внешнего облика, и внешнее уподобляется внутреннему. Тогда раб перестаёт замечать всё иное и пребывает в духовном созерцании, затрагивающем саму его сущность и порождающем особую любовь, воспламеняющую дух.')])
merge('v4-p336-05','v4-p337-01');merge('v4-p337-05','v4-p338-01')
